function Topbar() {
  return (
    <div style={{
      background: "#f0f0f0",
      borderBottom: "1px solid #d8d8d8",
      padding: "5px 20px",
      display: "flex",
      justifyContent: "space-between",
      fontSize: "12px"
    }}>

      {/* Left side - phone number */}
      <span>
        Call for Customer support:{" "}
        <span style={{ color: "#cc0000", fontWeight: "bold" }}>
          020 38989565
        </span>
      </span>

      {/* Right side - links */}
      <div>
        <a href="#" style={{ color: "#444", textDecoration: "none", marginLeft: "18px" }}>
          My Account
        </a>
        <a href="#" style={{ color: "#444", textDecoration: "none", marginLeft: "18px" }}>
          Wishlist
        </a>
        <a href="#" style={{ color: "#444", textDecoration: "none", marginLeft: "18px" }}>
          To Checkout
        </a>
      </div>

    </div>
  );
}

export default Topbar;
